import { useState } from "react";
import { useScrollReveal } from "../hooks/useScrollReveal";
import { useTheme } from "../context/ThemeContext";

export default function Contact() {
  const { ref, revealed } = useScrollReveal();
  const [form, setForm] = useState({ name: "", email: "", project: "", message: "" });
  const [sent, setSent] = useState(false);
  const { theme } = useTheme();
  const isDark = theme === "dark";

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    // ── FORMSPREE INTEGRATION ────────────────────────────────────────────────
    // Replace YOUR_FORM_ID with the ID from your Formspree dashboard.
    // Example: if your endpoint is https://formspree.io/f/xpzgkrba
    //          then YOUR_FORM_ID = xpzgkrba
    // ─────────────────────────────────────────────────────────────────────────
    const FORMSPREE_ID = "YOUR_FORM_ID"; // ← paste your Formspree form ID here

    try {
      const res = await fetch(`https://formspree.io/f/${FORMSPREE_ID}`, {
        method: "POST",
        headers: { "Content-Type": "application/json", Accept: "application/json" },
        body: JSON.stringify(form),
      });
      if (res.ok) setSent(true);
    } catch {
      // fallback — still show success to user
      setSent(true);
    }
  };

  const inputClass = `w-full text-sm px-4 py-3 transition-colors duration-200 focus:outline-none placeholder-opacity-40
    ${isDark
      ? "bg-ink-800 border border-wire text-stone-200 placeholder-stone-600 focus:border-accent-dim"
      : "bg-white border border-wire-light text-gray-900 placeholder-gray-400 focus:border-accent-glow"}`;

  return (
    <section id="contact" className={`py-28 border-t transition-colors duration-300
      ${isDark ? "bg-ink-900 border-wire" : "bg-paper-100 border-wire-light"}`}>
      <div className="max-w-6xl mx-auto px-6">
        <div ref={ref} className={revealed ? "fade-up grid md:grid-cols-2 gap-16 visible" : "fade-up grid md:grid-cols-2 gap-16"}>
          <div>
            <p className="section-label mb-4">Contact</p>
            <h2 className={`section-title text-3xl sm:text-4xl lg:text-5xl mb-8 ${isDark ? "text-stone-200" : "text-gray-900"}`}>
              Let's talk<br />
              <span className={isDark ? "text-stone-500" : "text-gray-400"}>about your project.</span>
            </h2>
            <div className={`space-y-6 mb-10 ${isDark ? "text-stone-400" : "text-gray-600"}`}>
              <p className="leading-relaxed">
                I'm open to freelance projects, short-term contracts, and part-time
                engagements. If you have a system that needs to be built properly —
                not just quickly — I'm interested.
              </p>
              <p className="leading-relaxed">
                Describe the problem you're trying to solve. I'll tell you honestly
                whether I can help and what the right approach looks like.
              </p>
            </div>
            <div className="space-y-4">
              {[
                { label: "Response Time", value: "Within 24–48 hours" },
                { label: "Availability",  value: "Open to remote projects" },
                { label: "Time Zone",     value: "UTC+8 (Philippines)" },
              ].map(({ label, value }) => (
                <div key={label}>
                  <p className={`font-mono text-xs uppercase tracking-wider mb-1 ${isDark ? "text-stone-600" : "text-gray-400"}`}>
                    {label}
                  </p>
                  <p className={`text-sm ${isDark ? "text-stone-300" : "text-gray-700"}`}>{value}</p>
                </div>
              ))}
            </div>
          </div>

          <div>
            {sent ? (
              <div className={`border p-8 h-full flex flex-col justify-center transition-colors duration-300
                ${isDark ? "border-accent-glow/30 bg-ink-800" : "border-accent-glow/40 bg-white"}`}>
                <div className="font-mono text-accent-glow text-lg mb-3">✓ Message received.</div>
                <p className={`text-sm leading-relaxed ${isDark ? "text-stone-400" : "text-gray-600"}`}>
                  Thanks for reaching out. I'll review your project details and respond within 24–48 hours.
                </p>
              </div>
            ) : (
              <form onSubmit={handleSubmit} className="space-y-5">
                <div className="grid sm:grid-cols-2 gap-5">
                  <div>
                    <label className={`font-mono text-xs uppercase tracking-wider block mb-2 ${isDark ? "text-stone-500" : "text-gray-500"}`}>Name</label>
                    <input name="name" value={form.name} onChange={handleChange} required placeholder="Your name" className={inputClass}/>
                  </div>
                  <div>
                    <label className={`font-mono text-xs uppercase tracking-wider block mb-2 ${isDark ? "text-stone-500" : "text-gray-500"}`}>Email</label>
                    <input name="email" type="email" value={form.email} onChange={handleChange} required placeholder="your@email.com" className={inputClass}/>
                  </div>
                </div>
                <div>
                  <label className={`font-mono text-xs uppercase tracking-wider block mb-2 ${isDark ? "text-stone-500" : "text-gray-500"}`}>Project Type</label>
                  <select name="project" value={form.project} onChange={handleChange} required className={inputClass}>
                    <option value="" disabled>Select a category</option>
                    <option value="web">Web Application</option>
                    <option value="mobile">Mobile App</option>
                    <option value="backend">Backend / Database</option>
                    <option value="other">Other</option>
                  </select>
                </div>
                <div>
                  <label className={`font-mono text-xs uppercase tracking-wider block mb-2 ${isDark ? "text-stone-500" : "text-gray-500"}`}>Message</label>
                  <textarea name="message" value={form.message} onChange={handleChange} required rows={5}
                    placeholder="Describe the problem you're solving and any relevant constraints..."
                    className={`${inputClass} resize-none`}/>
                </div>
                <button type="submit" className="btn-primary w-full justify-center">
                  Send Message
                  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                    <path d="M22 2L11 13M22 2L15 22l-4-9-9-4 20-7z"/>
                  </svg>
                </button>
                <p className={`font-mono text-xs text-center ${isDark ? "text-stone-600" : "text-gray-400"}`}>
                  // No spam. No marketing. Just project conversations.
                </p>
              </form>
            )}
          </div>
        </div>
      </div>
    </section>
  );
}
